macroScript CleanAI3DData
category:"3dflowhub"
toolTip:"Clean AI 3D Assets"
(
	fn cleanSceneObjects = (
		local sel = selection as array
		if sel.count == 0 then (
			print "No objects selected."
			return false
		)
		for obj in sel do (
			try (
				resetScale obj
				collapseStack obj
			) catch (
				print ("Failed on: " + obj.name)
			)
		)
		print "AI 3D asset scale and stack cleaned."
	);

	on execute do (
		undo "Clean AI 3D Data" on (
			cleanSceneObjects()
		)
	)
)
